SELECT event_date, brand_id, impressions, clicks, ctr
FROM agg_brand_daily
WHERE event_date = DATE '2017-05-12' AND brand_id = 61390;

SELECT campaign_id, clicks, impressions, ctr
FROM live_campaign_last6h
WHERE campaign_id = 31834;

SELECT COUNT(DISTINCT user_id) AS distinct_clickers
FROM fact_ad_events
WHERE is_click = 1;

SELECT COUNT(DISTINCT user_id) AS unique_click_users
FROM fact_ad_events
WHERE is_click = 1;

SELECT COUNT(DISTINCT user_id) AS people_clicked
FROM fact_ad_events
WHERE is_click = 1;
